import test from 'node:test';import assert from 'node:assert/strict';
import {createPcmResampler,createLearningRealtimeRecorder} from './realtimeRecorder.js';
for(const rate of [44100,48000])test(`continuous resampling at ${rate} is independent of block boundaries`,()=>{const input=Float32Array.from({length:rate*2},(_,i)=>Math.sin(i/21)*.4);const a=createPcmResampler(rate),b=createPcmResampler(rate);const whole=a.push(input);const parts=[];for(let i=0;i<input.length;i+=997)parts.push(...b.push(input.subarray(i,i+997)));assert.deepEqual(parts,[...whole]);assert.equal(parts.length,32000);});
function env(){let processor,stopped=0;class Context{sampleRate=48000;destination={};async resume(){}async close(){}createMediaStreamSource(){return{connect(){},disconnect(){}};}createGain(){return{gain:{value:1},connect(){},disconnect(){}};}createScriptProcessor(){return processor={connect(){},disconnect(){}};}}return{Context,mediaDevices:{getUserMedia:async()=>({getTracks:()=>[{stop(){stopped++;}}]})},feed:()=>processor.onaudioprocess({inputBuffer:{getChannelData:()=>new Float32Array(4800).fill(.2)}}),stopped:()=>stopped};}
test('audio is emitted while recording and exactly matches completed local WAV',async()=>{const e=env(),chunks=[];let ready=0,blob;const r=createLearningRealtimeRecorder({AudioContextClass:e.Context,mediaDevices:e.mediaDevices,onRecordingReady:()=>ready++,onChunk:x=>chunks.push(Buffer.from(x)),onAudioReady:x=>blob=x.blob});await r.start();e.feed();e.feed();assert.equal(ready,1);assert.ok(chunks.length);assert.equal(blob,undefined);r.stop();assert.deepEqual(Buffer.concat(chunks),Buffer.from(await blob.arrayBuffer()).subarray(44));assert.equal(e.stopped(),1);});
test('permission failure never opens upload and late granted permission after cancel is released',async()=>{let begin=0,resolve,stopped=0;const e=env();const r=createLearningRealtimeRecorder({AudioContextClass:e.Context,mediaDevices:{getUserMedia:()=>new Promise(r=>resolve=r)},onRecordingReady:()=>begin++});const starting=r.start();r.cancel();resolve({getTracks:()=>[{stop(){stopped++;}}]});await starting;assert.equal(begin,0);assert.equal(stopped,1);const denied=createLearningRealtimeRecorder({mediaDevices:{getUserMedia:async()=>{throw Object.assign(Error(),{name:'NotAllowedError'});}},onRecordingReady:()=>begin++});await denied.start();assert.equal(begin,0);});
